def find_sum_of_multiples_recursive(n, a, b):
    """
    This function takes three parameters, 'n', 'a', and 'b', and returns the sum of all the multiples of 'a' or 'b' below 'n' using recursion.

    Parameters:
    n (int): The upper limit.
    a (int): The first number.
    b (int): The second number.

    Returns:
    int: The sum of all the multiples of 'a' or 'b' below 'n'.
    """
    def sum_multiples(num, limit):
        if num >= limit:
            return 0
        elif num % a == 0 or num % b == 0:
            return num + sum_multiples(num + 1, limit)
        else:
            return sum_multiples(num + 1, limit)

    return sum_multiples(0, n)
